"""Pilot experiment configuration for collapse-aware-mixing MVP.

Validates spectral effective rank as a leading indicator of model collapse
in iterative synthetic training (Pythia-1B, 3 generations x 500M tokens).
"""

import os
from dataclasses import dataclass


@dataclass
class PilotConfig:
    # --- Model ---
    model_name: str = "EleutherAI/pythia-1b"

    # --- Training ---
    num_generations: int = 3                    # G0 (real), G1 (synth from G0), G2 (synth from G1)
    tokens_per_generation: int = 500_000_000    # 500M tokens per generation
    checkpoint_interval_tokens: int = 50_000_000  # save + eval every 50M tokens
    max_seq_length: int = 2048
    per_device_batch_size: int = 8
    gradient_accumulation_steps: int = 4
    learning_rate: float = 1e-5
    warmup_ratio: float = 0.05
    weight_decay: float = 0.01
    seed: int = 42
    bf16: bool = True
    gradient_checkpointing: bool = True

    # --- Synthetic data generation ---
    gen_temperature: float = 1.0
    gen_top_p: float = 0.95
    gen_batch_size: int = 32
    gen_max_new_tokens: int = 2048

    # --- Metrics ---
    spectral_num_samples: int = 50_000          # sequences for spectral effective rank
    spectral_batch_size: int = 64
    metrics_gen_tokens: int = 500_000           # tokens to generate at each ckpt for n-gram/coverage
    ppl_num_samples: int = 5_000                # sequences for PPL evaluation
    ppl_batch_size: int = 16

    # --- Data ---
    real_dataset: str = "openwebtext"
    holdout_size: int = 10_000                  # sequences reserved for evaluation

    # --- Paths ---
    output_dir: str = "./output"

    # --- Logging ---
    use_wandb: bool = True
    wandb_project: str = "collapse-aware-mixing"
    wandb_run_prefix: str = "pilot"

    # --- Derived properties ---

    @property
    def effective_batch_size(self) -> int:
        return self.per_device_batch_size * self.gradient_accumulation_steps

    @property
    def tokens_per_step(self) -> int:
        return self.max_seq_length * self.effective_batch_size

    @property
    def save_steps(self) -> int:
        return self.checkpoint_interval_tokens // self.tokens_per_step

    @property
    def max_steps(self) -> int:
        return self.tokens_per_generation // self.tokens_per_step

    def gen_dir(self, g: int) -> str:
        return os.path.join(self.output_dir, f"G{g}")

    def checkpoint_dir(self, g: int, step: int) -> str:
        return os.path.join(self.gen_dir(g), "training", f"checkpoint-{step}")

    def synthetic_data_path(self, g: int) -> str:
        return os.path.join(self.gen_dir(g), "synthetic_data")

    def metrics_path(self, g: int) -> str:
        return os.path.join(self.gen_dir(g), "metrics.jsonl")

    def summary_path(self) -> str:
        return os.path.join(self.output_dir, "pilot_summary.json")

"""Data loading, tokenization, and preprocessing for pilot experiments."""

import os
import logging
from typing import Tuple, List, Optional
from itertools import chain

import torch
from torch.utils.data import Dataset as TorchDataset, DataLoader
from datasets import load_dataset, Dataset, load_from_disk
from transformers import PreTrainedTokenizer

logger = logging.getLogger(__name__)


class PackedDataset(TorchDataset):
    """Pre-tokenized, fixed-length sequences for causal LM training."""

    def __init__(self, input_ids: List[List[int]]):
        self.input_ids = input_ids

    def __len__(self):
        return len(self.input_ids)

    def __getitem__(self, idx):
        ids = torch.tensor(self.input_ids[idx], dtype=torch.long)
        return {"input_ids": ids, "attention_mask": torch.ones_like(ids), "labels": ids.clone()}


def prepare_real_data(
    config, tokenizer: PreTrainedTokenizer
) -> Tuple[PackedDataset, PackedDataset]:
    """Load real data (OpenWebText), tokenize, pack, split into train/holdout."""
    cache_path = os.path.join(config.output_dir, "real_data_cache")

    if os.path.exists(cache_path):
        logger.info("Loading cached tokenized data from %s", cache_path)
        ds = load_from_disk(cache_path)
    else:
        num_train_seqs = config.tokens_per_generation // config.max_seq_length + 1
        num_total_seqs = num_train_seqs + config.holdout_size + 2000
        # ~400 tokens/doc average in OpenWebText
        num_docs = int(num_total_seqs * config.max_seq_length / 400) + 50_000

        logger.info("Loading %d documents from %s ...", num_docs, config.real_dataset)
        raw = load_dataset(
            config.real_dataset,
            split=f"train[:{num_docs}]",
            trust_remote_code=True,
        )

        logger.info("Tokenizing ...")
        tokenized = raw.map(
            lambda ex: tokenizer(ex["text"], truncation=False, add_special_tokens=False),
            batched=True,
            remove_columns=raw.column_names,
            num_proc=4,
            desc="Tokenizing",
        )

        logger.info("Packing into %d-token sequences ...", config.max_seq_length)

        def pack_fn(examples):
            flat = list(chain(*examples["input_ids"]))
            n = (len(flat) // config.max_seq_length) * config.max_seq_length
            return {
                "input_ids": [
                    flat[i : i + config.max_seq_length]
                    for i in range(0, n, config.max_seq_length)
                ]
            }

        ds = tokenized.map(
            pack_fn, batched=True, remove_columns=tokenized.column_names, num_proc=1
        )

        os.makedirs(cache_path, exist_ok=True)
        ds.save_to_disk(cache_path)
        logger.info("Cached %d packed sequences to %s", len(ds), cache_path)

    num_train = config.tokens_per_generation // config.max_seq_length
    num_holdout = min(config.holdout_size, len(ds) - num_train)

    train_ids = [ds[i]["input_ids"] for i in range(num_train)]
    holdout_ids = [ds[i]["input_ids"] for i in range(num_train, num_train + num_holdout)]

    logger.info(
        "Train: %d seqs (%.1fM tokens) | Holdout: %d seqs",
        len(train_ids),
        len(train_ids) * config.max_seq_length / 1e6,
        len(holdout_ids),
    )
    return PackedDataset(train_ids), PackedDataset(holdout_ids)


def prepare_synthetic_data(
    data_path: str, config, tokenizer: PreTrainedTokenizer
) -> PackedDataset:
    """Load generated synthetic data and wrap as PackedDataset."""
    logger.info("Loading synthetic data from %s", data_path)
    ds = load_from_disk(data_path)
    num_seqs = min(len(ds), config.tokens_per_generation // config.max_seq_length)

    input_ids = []
    for i in range(num_seqs):
        seq = ds[i]["input_ids"]
        if len(seq) >= config.max_seq_length:
            input_ids.append(seq[: config.max_seq_length])
        else:
            # pad short sequences with eos_token_id
            pad_id = tokenizer.eos_token_id or 0
            input_ids.append(seq + [pad_id] * (config.max_seq_length - len(seq)))

    logger.info("Loaded %d synthetic sequences", len(input_ids))
    return PackedDataset(input_ids)


def extract_token_ids(dataset: PackedDataset, max_tokens: Optional[int] = None) -> List[int]:
    """Flatten all sequences into a single token-id list for corpus-level metrics."""
    ids: List[int] = []
    for i in range(len(dataset)):
        ids.extend(dataset.input_ids[i])
        if max_tokens and len(ids) >= max_tokens:
            return ids[:max_tokens]
    return ids


def make_dataloader(dataset: PackedDataset, batch_size: int, shuffle: bool = False) -> DataLoader:
    return DataLoader(dataset, batch_size=batch_size, shuffle=shuffle, num_workers=2, pin_memory=True)

